'use strict';
const test=require('node:test'); const assert=require('node:assert/strict'); const fsp=require('node:fs/promises'); const fs=require('node:fs'); const os=require('node:os'); const path=require('node:path'); const zlib=require('node:zlib'); const {createLocalDb}=require('../server/lib/local-db'); const {createSyncSettings}=require('../server/lib/sync-settings'); const {buildSyncPackages,validateSyncPackage,SYNC_PACKAGE_DIR,SYNC_GZIP_SUFFIX,isBundleFile}=require('../server/lib/sync-package');
async function tmp(t,p){const root=await fsp.mkdtemp(path.join(os.tmpdir(),p));t.after(()=>fsp.rm(root,{recursive:true,force:true}));return root;} function droot(shared,db){return path.join(shared,'BUYER_LOG_SYNC','changes',encodeURIComponent(db.getDeviceId()));} async function advertise(sync){await sync.syncOnce();} async function readBundle(file){const b=await fsp.readFile(file);return JSON.parse((String(file).endsWith(SYNC_GZIP_SUFFIX)?zlib.gunzipSync(b):b).toString('utf8'));}
test('applying same v2 package repeatedly mutates state only once',async t=>{const root=await tmp(t,'bl-idempotent-'),sender=createLocalDb(path.join(root,'s','BuyerLogLocal.db')),receiver=createLocalDb(path.join(root,'r','BuyerLogLocal.db'));await sender.ensure();await receiver.ensure();await sender.queuePatch({id:'A',patch:{value:1}});const pkg=buildSyncPackages(await sender.pending(10),{deviceId:sender.getDeviceId()}).packages[0].manifest;const a=await receiver.applyPackage({packageId:pkg.packageId,sourceDeviceId:pkg.deviceId,firstSeq:pkg.firstSeq,lastSeq:pkg.lastSeq,events:pkg.events});const b=await receiver.applyPackage({packageId:pkg.packageId,sourceDeviceId:pkg.deviceId,firstSeq:pkg.firstSeq,lastSeq:pkg.lastSeq,events:pkg.events});assert.equal(a.applied,1);assert.equal(b.duplicate,true);assert.equal((await receiver.read()).records.A.value,1);assert.equal(Object.keys((await receiver.read()).appliedPackages).length,1);});
